def solve(path):
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root
        else:
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

def solve(nums):
    a = nums[:]  # copy
    n = len(a)
    # find pivot
    i = n - 2
    while i >= 0 and a[i] >= a[i+1]:
        i -= 1
    if i == -1:
        return sorted(a)
    # find rightmost successor greater than a[i]
    j = n - 1
    while a[j] <= a[i]:
        j -= 1
    a[i], a[j] = a[j], a[i]
    a[i+1:] = reversed(a[i+1:])
    return a

