        base_primes = [i for i in range(3, base_limit + 1, 2) if bs[i]]
    seg_size = 1 << 20
    for start in range(3, m, seg_size):
        end = min(start + seg_size, m)
        length = end - start
        seg = bytearray([1]) * length
        if start % 2 == 0:
