    """Greedy word wrap.
    Pack words into lines without exceeding *width* characters.
    Words are separated by a single space. If a single word is longer than
    *width*, it occupies a line by itself.
    """
    lines = []
    current = ''
    for w in words:
        if w == '':
            # Skip empty words; they add no length.
            continue
        if not current:
            current = w
        else:
            # Check if adding the word (plus a space) fits.
            if len(current) + 1 + len(w) <= width:
                current += ' ' + w
            else:
                lines.append(current)
                current = w
    if current:
        lines.append(current)
    return lines
