def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Handles None or non‑list gracefully by returning 0.
    """
    if not isinstance(nums, (list, tuple)):
        return 0
    if not nums:
        return 0
    import bisect
    tails = []
    for x in nums:
        # ensure x is comparable; if not, skip
        try:
            i = bisect.bisect_left(tails, x)
        except Exception:
            continue
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

