def solve(grid):
    """Count islands (connected components of 1s) in a 2D grid.
    Grid may be empty or ragged. Connectivity is 4-directional.
    """
    if not grid:
        return 0
    visited = set()
    count = 0
    rows = len(grid)
    for r in range(rows):
        cols = len(grid[r])
        for c in range(cols):
            if grid[r][c] != 1 or (r, c) in visited:
                continue
            count += 1
            # BFS
            stack = [(r, c)]
            visited.add((r, c))
            while stack:
                x, y = stack.pop()
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx, ny = x+dx, y+dy
                    if 0 <= nx < rows and 0 <= ny < len(grid[nx]) and grid[nx][ny] == 1 and (nx, ny) not in visited:
                        visited.add((nx, ny))
                        stack.append((nx, ny))
    return count

